import { trimScopedNavPages } from './trimScopedNavPages.js';
const page = (slug, extra = {}) => (Object.assign({ title: slug, href: `/${slug}`, description: `${slug} description` }, extra));
function descriptions(nav) {
    const out = {};
    const walk = (node) => {
        if (Array.isArray(node))
            return node.forEach(walk);
        if (typeof node !== 'object' || node === null)
            return;
        if ('href' in node && 'title' in node && typeof node.href === 'string') {
            out[node.href] = 'description' in node ? node.description : undefined;
            return;
        }
        Object.values(node).forEach(walk);
    };
    walk(nav);
    return out;
}
describe('trimScopedNavPages', () => {
    it('keeps only client fields on pages', () => {
        const nav = {
            pages: [
                page('a', {
                    sidebarTitle: 'A',
                    openapi: 'get /a',
                    deprecated: true,
                    playground: 'simple',
                    version: 'v2',
                    mode: 'wide',
                    autogeneratedByOpenApi: true,
                    authors: [{ name: 'x' }],
                    keywords: ['k'],
                    customFrontmatter: 'x',
                }),
            ],
        };
        expect(trimScopedNavPages(nav, '/a')).toEqual({
            pages: [
                {
                    title: 'a',
                    href: '/a',
                    sidebarTitle: 'A',
                    openapi: 'get /a',
                    deprecated: true,
                    playground: 'simple',
                    version: 'v2',
                    mode: 'wide',
                },
            ],
        });
    });
    it('keeps descriptions only on pagination neighbors', () => {
        const nav = {
            groups: [
                { group: 'One', pages: [page('a'), page('b')] },
                { group: 'Two', pages: [page('c'), page('d')] },
            ],
        };
        expect(descriptions(trimScopedNavPages(nav, '/b'))).toEqual({
            '/a': 'a description',
            '/b': undefined,
            '/c': 'c description',
            '/d': undefined,
        });
    });
    it('orders a group root before its pages', () => {
        const nav = {
            groups: [{ group: 'G', root: page('root'), pages: [page('a'), page('b')] }],
        };
        expect(descriptions(trimScopedNavPages(nav, '/a'))).toEqual({
            '/root': 'root description',
            '/a': undefined,
            '/b': 'b description',
        });
    });
    it('steps past neighbors some viewers cannot see', () => {
        const nav = {
            pages: [
                page('a'),
                page('hidden', { hidden: true }),
                page('current'),
                page('gated', { groups: ['admin'] }),
                page('b'),
                page('c'),
            ],
        };
        expect(descriptions(trimScopedNavPages(nav, '/current'))).toEqual({
            '/a': 'a description',
            '/hidden': 'hidden description',
            '/current': undefined,
            '/gated': 'gated description',
            '/b': 'b description',
            '/c': undefined,
        });
    });
    it('steps past pages under a hidden group or division', () => {
        const nav = {
            tabs: [
                {
                    tab: 'Docs',
                    groups: [
                        { group: 'One', pages: [page('current')] },
                        { group: 'Drafts', hidden: true, root: page('draft-root'), pages: [page('draft')] },
                        { group: 'Two', pages: [page('next'), page('after')] },
                    ],
                },
                { tab: 'Hidden', hidden: true, pages: [page('hidden-tab')] },
                { tab: 'Other', pages: [page('other')] },
            ],
        };
        expect(descriptions(trimScopedNavPages(nav, '/current'))).toEqual({
            '/current': undefined,
            '/draft-root': 'draft-root description',
            '/draft': 'draft description',
            '/next': 'next description',
            '/after': undefined,
            '/hidden-tab': undefined,
            '/other': undefined,
        });
        expect(descriptions(trimScopedNavPages(nav, '/after'))).toMatchObject({
            '/hidden-tab': 'hidden-tab description',
            '/other': 'other description',
        });
    });
    it('keeps descriptions a directory root lists', () => {
        const nav = {
            groups: [
                {
                    group: 'Dir',
                    directory: 'card',
                    root: page('dir'),
                    pages: [
                        page('child'),
                        {
                            group: 'Sub',
                            pages: [page('grandchild'), { group: 'Deep', pages: [page('deep')] }],
                        },
                    ],
                },
                { group: 'Other', pages: [page('x'), page('y')] },
            ],
        };
        expect(descriptions(trimScopedNavPages(nav, '/dir'))).toEqual({
            '/dir': undefined,
            '/child': 'child description',
            '/grandchild': 'grandchild description',
            '/deep': undefined,
            '/x': undefined,
            '/y': undefined,
        });
    });
    it('matches index hrefs like the client', () => {
        const nav = { pages: [page('a'), page('guide/index'), page('b')] };
        expect(descriptions(trimScopedNavPages(nav, '/guide'))).toEqual({
            '/a': 'a description',
            '/guide/index': undefined,
            '/b': 'b description',
        });
    });
    it('leaves division descriptions and global links alone', () => {
        const nav = {
            global: {
                anchors: [{ anchor: 'Blog', href: 'https://example.com', description: 'kept' }],
            },
            dropdowns: [
                {
                    dropdown: 'D',
                    description: 'dropdown description',
                    pages: [page('a')],
                },
            ],
        };
        expect(trimScopedNavPages(nav, '/a')).toEqual({
            global: {
                anchors: [{ anchor: 'Blog', href: 'https://example.com', description: 'kept' }],
            },
            dropdowns: [
                {
                    dropdown: 'D',
                    description: 'dropdown description',
                    pages: [{ title: 'a', href: '/a' }],
                },
            ],
        });
    });
    it('does not mutate the input', () => {
        const nav = {
            pages: [page('a', { keywords: ['k'] }), page('b'), page('c')],
        };
        const before = structuredClone(nav);
        trimScopedNavPages(nav, '/a');
        expect(nav).toEqual(before);
    });
});
